const scenes7=[{id:'snack',name:'간식 봉지',item:'간식',unit:'개',box:'봉지',boxUnit:'개',icon:'🍪'},{id:'pencil',name:'색연필 통',item:'색연필',unit:'자루',box:'통',boxUnit:'개',icon:'✏️'},{id:'flower',name:'꽃다발',item:'꽃',unit:'송이',box:'꽃다발',boxUnit:'개',icon:'🌷'},{id:'chair',name:'의자 줄',item:'의자',unit:'개',box:'줄',boxUnit:'줄',icon:'🪑'}];
let s7={cards:[],done:false};const scene7=()=>scenes7[s7.scene];
function escape7(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function story7(c){const d=scenes7[c.scene],item=c.item||d.item;return `${item}: 한 ${d.box}에 ${c.n}${d.unit}씩 있습니다. ${d.box==='줄'?'그런 줄은':'묶음은'} 모두 ${c.g}${d.boxUnit}입니다.`}
function question7(c){return `${c.item||scenes7[c.scene].item}은 모두 몇 ${scenes7[c.scene].unit}일까요?`}
function start7(){view='stage7';app.innerHTML=`<section class="activity"><span class="pill">7단계 · 내가 만드는 구구단 문제</span><h1>어떤 문제를 만들어 볼까요?</h1><p>장면을 고르고, 몇 개씩 몇 묶음인지 정해요. 서로 다른 장면 2개로 문제를 만들어 보세요.</p><div class="steps">${scenes7.map((d,i)=>`<button class="step" onclick="create7(${i})"><span style="font-size:2rem" aria-hidden="true">${d.icon}</span><strong>${d.name}</strong><small>${s7.cards.some(c=>c.scene===i)?'✓ 만든 장면 · 또 만들기':'이 장면으로 만들기'}</small></button>`).join('')}</div><div class="actions">${s7.cards.length?'<button class="primary" onclick="gallery7()">내 문제 카드 전시 보기</button>':''}<button onclick="start6()">구구단 카드 짧게 연습하기</button></div>${s7.done?'<p class="feedback good">서로 다른 두 장면을 완성했어요. 7단계 완료!</p>':''}</section>`}
function create7(scene){Object.assign(s7,{scene,n:scene===1?4:3,g:3,item:scenes7[scene].item,phase:'setup',marked:[],focus:-1,question:false,msg:'한 묶음의 개수와 묶음의 수를 각각 정해요.',saved:false});render7()}
function number7(key,value){s7[key]=value;s7.marked=[];render7()}
function picture7(c,interactive=false){const d=scenes7[c.scene];return `<div class="maker-groups">${Array.from({length:c.g},(_,i)=>`<${interactive?'button':'div'} class="maker-group ${interactive&&s7.focus===i?'chosen':''}" ${interactive?`onclick="mark7(${i})" aria-label="${i+1}번째 묶음, ${c.n}${d.unit}"`:''}><small>${i+1}${d.boxUnit}</small><div>${Array(c.n).fill(`<span aria-hidden="true">${d.icon}</span>`).join('')}</div></${interactive?'button':'div'}>`).join('')}</div>`}
function mark7(i){s7.focus=i;if(!s7.marked.includes(i))s7.marked.push(i);s7.msg=`${i+1}번째 묶음에 ${s7.n}${scene7().unit}씩 있어요. 모든 묶음을 하나씩 짚어 확인해요.`;render7()}
function setup7(){const field=document.querySelector('#itemName7');if(field)s7.item=field.value.trim().slice(0,20)||scene7().item;s7.phase='picture';s7.marked=[];s7.msg='그림과 문장을 나란히 살펴봐요. 각 묶음을 한 번씩 눌러 확인해요.';render7()}
function confirmPicture7(){if(s7.marked.length!==s7.g)return;s7.phase='question';s7.msg='친구가 무엇을 구하면 될까요? 질문을 골라 완성해요.';render7()}
function chooseQuestion7(ok){if(!ok){s7.msg='이번 문제는 물건이 모두 몇 개인지 묻는 문제예요. 전체 개수를 묻는 질문을 골라요.';render7();return}s7.question=true;s7.phase='equation';s7.focus=-1;s7.msg='문장의 묶음에 맞게 앞의 수, 뒤의 수, 답을 붙여요.';render7()}
function check7(a,b,total){if(![a,b,total].every(Number.isInteger)){s7.msg='세 칸을 모두 숫자로 채워 주세요.';render7();return}if(a!==s7.n){s7.focus=0;s7.msg=`${a*b===s7.n*s7.g?'전체 개수는 같지만, 지금 문장의 묶음을 먼저 살펴봐요. ':''}한 ${scene7().box}에는 몇 ${scene7().unit}씩 있나요? 첫 수는 그 개수예요.`;render7();return}if(b!==s7.g){s7.focus=-1;s7.msg=`그런 묶음이 몇 개 있나요? 둘째 수는 묶음의 수예요.`;render7();return}if(total!==s7.n*s7.g){s7.msg='식의 두 수는 잘 찾았어요. 묶음 그림을 세거나 아는 식을 이용해 전체 개수를 다시 찾아봐요.';render7();return}if(s7.phase==='solve'){if(!s7.saved){s7.cards.push({scene:s7.scene,n:s7.n,g:s7.g,item:s7.item});s7.saved=true}s7.done=new Set(s7.cards.map(c=>c.scene)).size>=2;s7.phase='success';s7.msg='그림·문장·식이 모두 맞아요! 내 문제 카드에 모았어요.'}else{s7.phase='verify';s7.msg='한 묶음의 개수, 묶음의 수, 전체 개수를 모두 연결했어요.'}render7()}
function solve7(){s7.phase='solve';s7.focus=-1;s7.msg='방금 붙인 식과 답을 가렸어요. 문제만 보고 다시 식을 만들어 봐요.';render7()}
function render7(){view='stage7';const d=scene7(),p=s7.phase;let content='';if(p==='setup'){content=`<label for="each7">한 ${d.box}에 몇 ${d.unit}씩?</label><select id="each7" onchange="number7('n',Number(this.value))">${[2,3,4,5,6,7,8,9].map(n=>`<option ${n===s7.n?'selected':''}>${n}</option>`).join('')}</select><label for="groups7">그런 묶음은 몇 개?</label><select id="groups7" onchange="number7('g',Number(this.value))">${[2,3,4,5,6].map(n=>`<option ${n===s7.g?'selected':''}>${n}</option>`).join('')}</select>${picture7(s7)}<details><summary>물건 이름 바꾸기 · 선택</summary><p class="small">그림과 단위에 어울리는 이름으로 바꿔요. 예: 색연필 → 빨간 색연필</p><label for="itemName7">물건 이름</label><input id="itemName7" maxlength="20" value="${escape7(s7.item)}" oninput="s7.item=this.value"></details><button class="primary" onclick="setup7()">이 묶음으로 만들기 →</button>`}else{content=`<div class="story-pair"><div>${picture7(s7,p==='picture'||p==='equation')}</div><div class="story-text"><p>${escape7(story7(s7))}</p>${s7.question?`<strong>${escape7(question7(s7))}</strong>`:''}</div></div>`;if(p==='picture')content+=`<button class="primary" onclick="confirmPicture7()" ${s7.marked.length!==s7.g?'disabled':''}>그림과 문장이 맞아요</button>`;if(p==='question')content+=`<div class="choices"><button onclick="chooseQuestion7(false)">물건의 색깔은 무엇일까요?</button><button onclick="chooseQuestion7(true)">${escape7(question7(s7))}</button></div>`;if(p==='equation'||p==='solve')content+=`<form id="equationForm7"><div class="equation-inputs"><label>한 묶음에 몇 개씩<input id="first7" type="number" min="1" max="9" inputmode="numeric" required></label><b>×</b><label>몇 묶음<input id="second7" type="number" min="1" max="9" inputmode="numeric" required></label><b>=</b><label>모두 몇 개<input id="total7" type="number" min="1" max="81" inputmode="numeric" required></label></div><button class="primary" type="submit">${p==='solve'?'내 문제 확인하기':'식과 답 붙이기'}</button></form>`;if(p==='verify')content+=`<div class="equation">${s7.n} × ${s7.g} = ${s7.n*s7.g}</div><p>첫 수 ${s7.n}: 한 묶음에 ${s7.n}${d.unit}씩<br>둘째 수 ${s7.g}: ${s7.g}묶음<br>답 ${s7.n*s7.g}: 모두 ${s7.n*s7.g}${d.unit}</p><button class="primary" onclick="solve7()">식과 답을 가리고 내 문제 풀기</button>`;if(p==='success')content+=`<div class="equation">${s7.n} × ${s7.g} = ${s7.n*s7.g}</div><p>${s7.done?'서로 다른 장면 두 개를 완성했어요!':'다른 장면으로 문제를 하나 더 만들어 볼까요?'}</p><div class="actions"><button onclick="start7()">다른 장면 고르기</button><button class="primary" onclick="gallery7()">내 문제 카드 전시</button></div>`}app.innerHTML=`<div class="topline"><span class="pill">7단계 · ${d.name} 문제 만들기</span><button onclick="start7()">장면 다시 고르기</button></div><section class="activity"><h1 class="instruction">${{setup:'내가 정하는 묶음',picture:'그림과 문장 확인하기',question:'친구에게 물어볼 질문',equation:'식과 답 붙이기',verify:'세 가지가 맞는지 확인해요',solve:'내가 만든 문제 풀어 보기',success:'문제 카드 완성!'}[p]}</h1><div class="workspace">${content}</div><p class="feedback ${p==='success'?'good':''}" role="status">${s7.msg}</p></section>`;const form=document.querySelector('#equationForm7');if(form)form.onsubmit=e=>{e.preventDefault();check7(...['first7','second7','total7'].map(id=>{const v=document.querySelector('#'+id).value;return v.trim()===''?NaN:Number(v)}))}}
function cardHTML7(c,i){return `<article class="problem-card"><span class="pill">내 문제 ${i+1}</span><p>${escape7(story7(c))}</p>${picture7(c)}<strong>${escape7(question7(c))}</strong><details><summary>뒤집어 식과 답 확인하기</summary><div class="equation">${c.n} × ${c.g} = ${c.n*c.g}</div><p>한 묶음에 ${c.n}개씩, ${c.g}묶음이에요.</p></details></article>`}
function gallery7(){view='stage7';import6();const mixed=s6.bank.slice(0,4);app.innerHTML=`<section class="activity"><span class="pill">7단계 · 내 문제 카드 전시</span><h1>${s7.done?'내가 만든 문제를 풀어 보세요!':'문제 카드가 모이고 있어요'}</h1><p>완성한 장면 ${new Set(s7.cards.map(c=>c.scene)).size} / 2개 · 카드를 보고 식을 만든 뒤 답을 열어 보세요.</p><div class="problem-gallery">${s7.cards.map(cardHTML7).join('')}</div><div class="actions"><button onclick="start7()">문제 더 만들기</button><button onclick="download7()" ${s7.cards.length?'':'disabled'}>문제 카드 파일로 저장</button></div><p class="small">카드는 이 브라우저에 저장돼요. 파일로 저장하면 다른 기기에서도 열어 풀 수 있어요. 다른 사람에게 자동으로 전송되지 않아요.</p>${s7.done?`<h2>8단계에서 함께 섞어 볼 카드</h2><p>내 문제 한 장과 구구단 카드 네 장을 함께 만나 봐요.</p>${cardHTML7(s7.cards[0],0)}<div class="saved-cards">${mixed.map(c=>`<article><strong>${c.key} = ?</strong><details><summary>답 확인</summary>${c.answer}</details></article>`).join('')}</div><p class="small">8단계에서 문제 형태를 섞어 다시 풀어 보세요.</p>`:''}<div class="actions"><button class="primary" onclick="start8()">8단계 섞어 풀기</button><button onclick="start6()">구구단 카드함 열기</button><button class="primary" onclick="home()">전체 단계</button></div></section>`}
function exportHTML7(){return `<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>내가 만든 구구단 문제 카드</title><style>body{font:18px/1.7 system-ui,sans-serif;max-width:900px;margin:30px auto;padding:20px;color:#182947}.problem-card{border:2px solid #b5caf7;border-radius:20px;padding:24px;margin:22px 0;break-inside:avoid}.maker-groups{display:flex;flex-wrap:wrap;gap:10px;margin:20px 0}.maker-group{border:1px solid #b5caf7;padding:12px;border-radius:12px;max-width:150px}.maker-group small{display:block}.maker-group span{display:inline-block}.equation{font-size:28px;font-weight:bold}summary{cursor:pointer;padding:12px}h1{font-size:28px}</style><h1>내가 만든 구구단 문제 카드</h1><p>문제를 풀어 본 뒤 ‘뒤집어 식과 답 확인하기’를 누르세요.</p>${s7.cards.map(cardHTML7).join('')}</html>`}
function download7(){const blob=new Blob([exportHTML7()],{type:'text/html;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='내가-만든-구구단-문제.html';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
